const $=s=>document.querySelector(s),A=CatalogAnalytics,escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let rows=[],page='catalog';function selection(){return A.filter(rows,{query:$('#query').value,type:$('#type').value,country:$('#country').value,year:+$('#year').value})}function bars(items){if(!items.length)return '<p class="empty">No data in this selection.</p>';const max=Math.max(...items.map(x=>x.count));return items.map(x=>`<div class="bar-row"><div><span>${escapeHTML(x.name)}</span><b>${x.count.toLocaleString()}</b></div><div class="track"><div class="fill" style="width:${x.count/max*100}%"></div></div></div>`).join('')}function timeline(data){const items=A.groups(data,r=>[String(r.releaseYear)]).sort((a,b)=>+a.name-+b.name);if(!items.length)return '<p class="empty">No releases match your filters.</p>';const W=700,H=230,p=30,step=(W-2*p)/items.length,max=Math.max(...items.map(x=>x.count));let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Titles by original release year">`;for(let i=0;i<4;i++){let y=H-25-i*(H-50)/3;svg+=`<line x1="${p}" x2="${W-p}" y1="${y}" y2="${y}" stroke="#e2ded6"/><text x="0" y="${y+4}" fill="#766f66" font-size="9">${Math.round(max*i/3)}</text>`}items.forEach((x,i)=>{let h=x.count/max*(H-50);svg+=`<rect x="${p+i*step+step*.2}" y="${H-25-h}" width="${step*.6}" height="${h}" rx="0" fill="#b3543b"><title>${x.name}: ${x.count} titles</title></rect>`;if(i%Math.max(1,Math.ceil(items.length/7))===0)svg+=`<text x="${p+i*step}" y="${H-6}" fill="#766f66" font-size="9">${x.name}</text>`});return svg+'</svg>'}function render(){let data=selection(),movies=data.filter(r=>r.type==='Movie').length,tv=data.length-movies,countries=new Set(data.flatMap(r=>A.tokens(r.country))).size,years=data.map(r=>r.releaseYear);$('#metrics').innerHTML=[['Titles in view',data.length,'Current selection'],['Movies',movies,'Movie entries'],['TV shows',tv,'TV entries'],['Countries',countries,'Listed production countries']].map(([label,count,caption])=>`<div class="metric"><small>${label}</small><strong>${count.toLocaleString()}</strong><span>${caption}</span></div>`).join('');$('#timeline').innerHTML=timeline(data);let fraction=data.length?movies/data.length*100:0;$('#mix').innerHTML=`<div class="format-total"><strong>${data.length.toLocaleString()}</strong><span>titles in this selection</span></div><div class="format-bar" role="img" aria-label="${movies} movies and ${tv} TV shows"><span style="width:${fraction}%"></span></div><div class="mix-label"><span>Movies</span><b>${movies} <small>${fraction.toFixed(0)}%</small></b></div><div class="mix-label"><span>TV shows</span><b>${tv} <small>${data.length?(100-fraction).toFixed(0):0}%</small></b></div>`;$('#countries').innerHTML=bars(A.groups(data,r=>A.tokens(r.country)).slice(0,5));$('#breakdown-title').textContent=page==='catalog'?'Genres':'Content ratings';$('#breakdown-note').textContent=page==='catalog'?'One title can have multiple genres.':'Ratings describe catalogue entries, not audience reviews.';$('#breakdown').innerHTML=bars(A.groups(data,r=>page==='catalog'?A.tokens(r.genres):[r.rating||'Unknown']).slice(0,6));$('#titles').innerHTML=data.slice(0,100).map(r=>`<tr><td>${escapeHTML(r.title)}</td><td><span class="type">${escapeHTML(r.type)}</span></td><td>${r.releaseYear}</td><td>${escapeHTML(r.country||'Unknown')}</td><td>${escapeHTML(r.rating||'Unknown')}</td></tr>`).join('');$('#table-note').textContent=`Showing ${Math.min(100,data.length)} of ${data.length.toLocaleString()} filtered titles.`;$('#explorer').hidden=page!=='catalog'}function reset(){for(const id of ['query','type','country','year'])$('#'+id).value=id==='query'?'':id==='year'?'0':'All';render()}function setRows(data,label){rows=data;$('#country').innerHTML='<option>All</option>'+[...new Set(rows.flatMap(r=>A.tokens(r.country)))].sort().map(x=>`<option>${escapeHTML(x)}</option>`).join('');$('#source').textContent=label;$('#error').hidden=true;reset()}async function sample(){try{const response=await fetch('sample.json');if(!response.ok)throw Error('Sample could not load. Import your own CSV.');setRows(await response.json(),'Illustrative sample · 48 invented titles · not Netflix’s full catalogue')}catch(e){showError(e.message)}}function showError(text){$('#error').textContent=text;$('#error').hidden=false}for(const id of ['query','type','country','year'])$('#'+id).addEventListener(id==='query'?'input':'change',render);$('#clear').onclick=reset;$('#sample').onclick=sample;$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20_000_000)throw Error('Choose a CSV smaller than 20 MB.');const result=A.catalog(await file.text());setRows(result.rows,`Imported: ${file.name} · ${result.rows.length.toLocaleString()} valid titles · ${result.skipped} invalid rows skipped`)}catch(e){showError(e.message)}finally{$('#file').value=''}};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x===b));$('#crumb').textContent=page==='catalog'?'Catalogue overview':'Trends & distribution';render()});$('#export').onclick=()=>{let columns=['show_id','title','type','release_year','country','listed_in','rating'];let cells=selection().map(r=>[r.id,r.title,r.type,r.releaseYear,r.country,r.genres,r.rating]);const safe=v=>{let s=String(v);if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const csv=[columns,...cells].map(r=>r.map(safe).join(',')).join('\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='streamlens-selection.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};sample();

$('#import-button').onclick=()=>$('#file').click();
